namespace CatCafePreview {public sealed class StandaloneOutcomeSmoke:MonoBehaviour {
 string output;int checks;bool failed;static BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 public static LocalCafeBackend Create(string path,string cause){var r=StandaloneEncounterConversationSmoke.Rules();r.goal_stages=new[]{new GoalStageRule{days=1,target=9999}};r.starting_funds=cause=="funds"?1:20000;r.starting_popularity=100;if(cause=="popularity"){r.runaway_threshold=0;r.popularity_loss=1000;}r.intake.day=r.regular_introduction.day=9999;r.growth.threshold=10000;return new LocalCafeBackend(path,r);}
 static void Good(LocalCafeBackend b,string kind,string choice=null,int slot=1)=>StandaloneDispatchConversationSmoke.Good(b,kind,choice,slot:slot);
 public static void Setup(LocalCafeBackend b){Good(b,"new_game","popularity");if(b.Simulation.Rules.runaway_threshold==0){Good(b,"set_shifts");Good(b,"start_business");int safety=0;while(b.Simulation.State.phase=="open" && safety++<1000)Good(b,"advance_business");}else Good(b,"day_off");}
 public static int BackendChecks(string folder,bool restart){int n=0;Action<bool,string> ck=(ok,label)=>{n++;if(!ok)throw new Exception(label);};
 foreach(var cause in new[]{"expired","funds","popularity"}){string path=Path.Combine(folder,cause);var b=Create(path,cause);
 if(restart){Good(b,"load_game",slot:2);ck(b.Outcome.progress.node==2 && b.Outcome.progress.page_offset==8,"Restart partial");Good(b,"load_game",slot:4);ck(b.Outcome.progress.completed,"Restart completed");}
 Setup(b);var o=b.Outcome;ck(o.day==1,"Captured next day instead of resolution");ck(o!=null && o.cause==cause && b.OutcomePending,"Cause mismatch");ck(cause=="expired"?b.Simulation.GoalWaiting:b.Simulation.State.goal.Last().status=="active","Deadline/termination priority changed");
 ck(!b.Replays.Load().entries.Any(e=>e.branch_id==cause && e.conversation_id==CafeOutcome.Id) || restart || File.Exists(Path.Combine(path,"slot-4.json")),"Unviewed archived");
 ck(StandaloneEncounterConversationSmoke.Send(b,"continue_goal").result!=UnityEngine.Networking.UnityWebRequest.Result.Success,"Unread continue allowed");
 string facts=string.Join("",o.Lines().Select(l=>l.text));for(int node=0;node<=o.Lines().Length;node++){o.progress.node=node;o.progress.page_offset=node==2?8:0;Good(b,"save_game",slot:3);Good(b,"load_game",slot:3);o=b.Outcome;ck(o.progress.node==node && o.progress.page_offset==(node==2?8:0) && facts==string.Join("",o.Lines().Select(l=>l.text)),"Position/facts lost");}
 o.progress.node=2;o.progress.page_offset=8;Good(b,"save_game",slot:2);o.progress.node=o.Lines().Length;o.progress.page_offset=0;o.progress.completed=true;o.progress.viewed_branches=new[]{cause};b.RememberViewedConversations();b.RememberViewedConversations();Good(b,"save_game",slot:4);ck(b.Replays.Load().entries.Count(e=>e.conversation_id==CafeOutcome.Id && e.branch_id==cause)==1,"Archive duplicate/missing");
 if(cause=="expired"){Good(b,"continue_goal");ck(!b.OutcomePending && b.Simulation.State.goal.Last().continued,"Continuation blocked");Good(b,"day_off");ck(facts==string.Join("",b.Outcome.Lines().Select(l=>l.text)),"Facts changed after next day");}
 else ck(StandaloneEncounterConversationSmoke.Send(b,"next_day").result!=UnityEngine.Networking.UnityWebRequest.Result.Success,"Ended business resumed");
 var bad=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(path,"slot-4.json")));bad.outcome.progress.node=999;bool rejected=false;try{CafeOutcome.Validate(bad.outcome,bad.state);}catch(ArgumentException){rejected=true;}ck(rejected,"Invalid node accepted");
 var old=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(path,"slot-4.json")));old.outcome=null;old.slot=5;File.WriteAllText(Path.Combine(path,"slot-5.json"),JsonUtility.ToJson(old));string legacyDir=Path.Combine(path,"legacy-check-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(legacyDir);File.Copy(Path.Combine(path,"slot-5.json"),Path.Combine(legacyDir,"slot-5.json"));var legacyOnly=Create(legacyDir,cause);Good(legacyOnly,"load_game",slot:5);legacyOnly.RememberViewedConversations();ck(legacyOnly.OutcomePending && legacyOnly.Replays.Load().entries.Length==0,"Legacy invented Extra");
 Good(b,"load_game",slot:5);ck(b.OutcomePending && b.Outcome.legacy && !b.Outcome.progress.completed,"Old pending invented completion");
 if(cause=="expired"){old.state.goal.Last().continued=true;old.slot=6;File.WriteAllText(Path.Combine(path,"slot-6.json"),JsonUtility.ToJson(old));Good(b,"load_game",slot:6);ck(b.Outcome==null,"Old continued reblocked");}
 Good(b,"new_game","free");ck(b.Outcome==null && b.Replays.Load().entries.Any(e=>e.conversation_id==CafeOutcome.Id),"New game leaked/lost archive");
 }
 var free=Create(Path.Combine(folder,"free"),"expired");Good(free,"new_game","bond");Good(free,"day_off");ck(free.Outcome==null && free.Simulation.State.game_over==null,"Timeless goal failed");
 var auto=Create(Path.Combine(folder,"auto-"+Guid.NewGuid().ToString("N")),"expired");Good(auto,"new_game","popularity");auto.Simulation.StartAutoplay("popularity","clear",3);auto.Simulation.Execute("day_off");Good(auto,"step_autoplay");ck(auto.OutcomePending && !auto.Simulation.State.autoplay.running,"Autoplay ending deadlock");
 // Composite historical expired record plus a later terminal result: never launch two conversations.
 var both=Create(Path.Combine(folder,"composite-"+Guid.NewGuid().ToString("N")),"expired");Setup(both);var st=both.Simulation.State;st.funds=0;st.game_over="funds";var combined=both.Outcome;ck(combined.cause=="funds" && combined.prior_expired_day==1 && combined.Lines()[2].text.Contains("期限内未達と記録"),"Existing expired record lost at termination");
 return n;}
 void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
 void Fail(Exception e){if(failed)return;failed=true;File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());Debug.LogException(e);Application.Quit(1);}
 void Log(string m,string stack,LogType t){if(t==LogType.Error || t==LogType.Exception || t==LogType.Assert)Fail(new Exception(m+stack));}void OnDestroy(){Application.logMessageReceived-=Log;}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--catcafe-outcome-check");if(i<0)return;var q=new GameObject("Outcome QA").AddComponent<StandaloneOutcomeSmoke>();DontDestroyOnLoad(q);q.output=Path.GetFullPath(a[i+1]);Directory.CreateDirectory(q.output);Application.runInBackground=true;Application.logMessageReceived+=q.Log;try{q.checks=BackendChecks(Path.Combine(q.output,"cases"),a.Contains("--outcome-restart"));q.StartCoroutine(q.Guard());}catch(Exception e){q.Fail(e);}}
 IEnumerator Guard(){var run=Run();while(true){bool more;try{more=run.MoveNext();}catch(Exception e){Fail(e);yield break;}if(!more)yield break;yield return run.Current;}}
 IEnumerator Run(){
 foreach(var cause in new[]{"expired","funds","popularity"}){
 var b=Create(Path.Combine(output,"ui-"+cause+"-"+Guid.NewGuid().ToString("N")),cause);Setup(b);CafeBackends.UseLocal(b);SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var p=FindObjectOfType<ContentPreview>();var ui=p.GetComponent<OutcomeConversationPanel>();Check(ui!=null && ui.Showing,"UI missing "+cause);var o=b.Outcome;typeof(AcquisitionConversationPanel).GetField("revealed",Hidden).SetValue(ui,0f);ui.Next();ui.Next();Check(o.progress.node==0,"Repeated click skipped");yield return null;ui.Next();Check(o.progress.node==1,"Next failed");ui.Close();yield return null;Check(!ui.Showing,"Close failed");if(cause=="expired")p.GetComponent<PythonGoalPanel>().Continue();else p.GetComponent<PythonGameOverPanel>().panel.GetComponentsInChildren<Button>().Single(x=>x.name=="結末を再開").onClick.Invoke();yield return null;Check(ui.Showing && o.progress.node==1,"Resume lost position");
 var host=typeof(AcquisitionConversationPanel).GetField("panel",Hidden).GetValue(ui) as GameObject;host.GetComponentsInChildren<Button>(true).Single(x=>x.name=="バックログ").onClick.Invoke();yield return null;Check(ui.HistoryScroll.gameObject.activeInHierarchy,"Backlog missing");yield return null;host.GetComponentsInChildren<Button>(true).Single(x=>x.name=="バックログ").onClick.Invoke();yield return null;
 o.progress.node=2;o.progress.page_offset=0;CafeOptions.Current.instant=true;ui.Refresh();Canvas.ForceUpdateCanvases();int pages=0;string text="";while(o.progress.node==2 && pages++<12){ui.Refresh();var body=typeof(AcquisitionConversationPanel).GetField("body",Hidden).GetValue(ui) as Text;var gen=new TextGenerator();var settings=body.GetGenerationSettings(new Vector2(body.rectTransform.rect.width,10000));settings.verticalOverflow=VerticalWrapMode.Overflow;gen.Populate(body.text,settings);Check(gen.lineCount<=3,"More than three lines");text+=body.text;ui.Next();yield return null;}Check(pages>=2 && text.Replace("\n","")==o.Lines()[2].text.Replace("\n",""),"Pagination lost text");
 o.progress.node=o.Lines().Length;o.progress.page_offset=0;ui.Refresh();yield return null;ui.Next();yield return null;Check(o.progress.completed && !ui.Showing,"Completion failed");Check(cause=="expired"?p.GetComponent<PythonGoalPanel>().panel.activeSelf:p.GetComponent<PythonGameOverPanel>().panel.activeSelf,"Result missing");Good(b,"save_game",slot:7);
 SceneManager.LoadScene("CatCafeTitle");yield return new WaitForSecondsRealtime(2);var extra=FindObjectOfType<PythonTitleScreen>().GetComponent<TitleExtraPanel>();extra.Open();extra.Panel.transform.Find("エンディング").GetComponent<Button>().onClick.Invoke();extra.OpenReplay(CafeOutcome.Id+"/"+cause);yield return null;Check(extra.Replay.Showing,"Extra locked");string before=JsonUtility.ToJson(b.Simulation.State);extra.Replay.Next();yield return null;extra.Replay.Close();Check(before==JsonUtility.ToJson(b.Simulation.State),"Extra mutated game");Good(b,"load_game",slot:7);SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);Check(b.Outcome.progress.completed,"Title/load lost result");
 }
 File.WriteAllText(Path.Combine(output,"result.txt"),"PASS: "+checks+" outcome checks; zero Unity errors.");var demo=Create(Path.Combine(output,"manual"),"funds");Setup(demo);CafeBackends.UseLocal(demo);SceneManager.LoadScene("CatCafePythonState");
 }
